    const cx = 120, cy = 110, L = 100, rad = (a * Math.PI) / 180, x2 = r1(cx + L * Math.cos(rad)), y2 = r1(cy - L * Math.sin(rad)), t = ((o.rot || 0) * Math.PI) / 180;
